package com.starlight.greetings.operations;
import com.starlight.greetings.domain.auth.SignupValidator; import java.nio.charset.StandardCharsets; import java.security.SecureRandom; import java.util.*; import javax.crypto.Cipher; import javax.crypto.spec.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.ApplicationArguments; import org.springframework.boot.ApplicationRunner; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Component;
@Component @ConditionalOnProperty(name="starlight.reset-admin-totp",havingValue="true") public class AdminTotpResetter implements ApplicationRunner {private static final String A="ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";private final JdbcTemplate jdbc;private final String key,nickname;private final SecureRandom random=new SecureRandom();public AdminTotpResetter(JdbcTemplate jdbc,@Value("${ADMIN_TOTP_KEY:}")String key,@Value("${ADMIN_NICKNAME:}")String nickname){this.jdbc=jdbc;this.key=key;this.nickname=nickname;}public void run(ApplicationArguments args)throws Exception{var name=new SignupValidator().nickname(nickname);byte[] raw=Base64.getDecoder().decode(key);if(raw.length!=32)throw new IllegalStateException("ADMIN_TOTP_KEY must decode to 32 bytes");String secret=secret();int n=jdbc.update("update users set totp_secret_ciphertext=?,last_totp_step=-1 where nickname_key=? and role='admin' and status='active'",encrypt(secret,raw),name.key());if(n==0)throw new IllegalStateException("Admin account not found");jdbc.update("update sessions set revoked_at=now() where user_id in (select id from users where nickname_key=? and role='admin') and revoked_at is null",name.key());System.out.println("TOTP secret (save once): "+secret);}private String secret(){byte[] input=new byte[20];random.nextBytes(input);int bits=0,v=0;StringBuilder out=new StringBuilder();for(byte b:input){v=(v<<8)|(b&255);bits+=8;while(bits>=5){out.append(A.charAt((v>>(bits-5))&31));bits-=5;}}if(bits>0)out.append(A.charAt((v<<(5-bits))&31));return out.toString();}private String encrypt(String s,byte[] key)throws Exception{byte[] iv=new byte[12];random.nextBytes(iv);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,new SecretKeySpec(key,"AES"),new GCMParameterSpec(128,iv));byte[] all=c.doFinal(s.getBytes(StandardCharsets.UTF_8));int split=all.length-16;return Base64.getUrlEncoder().withoutPadding().encodeToString(iv)+"."+Base64.getUrlEncoder().withoutPadding().encodeToString(Arrays.copyOfRange(all,split,all.length))+"."+Base64.getUrlEncoder().withoutPadding().encodeToString(Arrays.copyOf(all,split));}}
